"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisFooterContent } from "./components/footer-sections/content";
import View1 from "./components/footer-sections/variants/02-wordmark";
const variants = {"wordmark":View1};
export type { ArtemisFooterClock, ArtemisFooterColumn, ArtemisFooterColumnLink, ArtemisFooterContent, ArtemisFooterImage, ArtemisFooterLink, ArtemisFooterNewsletter, ArtemisFooterSocialLink } from "./components/footer-sections/content";
export interface ArtemisFooterSectionsProps { className?: string; variant?: "wordmark"; /** The words on the footer; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisFooterContent>; }
export function ArtemisFooterSections({ className, variant = "wordmark", content }: ArtemisFooterSectionsProps) {const View = variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal
import type { ComponentType } from "react";

/** The words on a link, and where it goes. Links to other sites (http or https) open in a new tab. */
export interface ArtemisFooterLink {
  label: string;
  href: string;
}

/** A link in a column. */
export interface ArtemisFooterColumnLink extends ArtemisFooterLink {
  /** Shows the link in the stronger style, for a "browse all" link. landscape. */
  highlight?: boolean;
}

/** A small heading over a list of links. */
export interface ArtemisFooterColumn {
  title: string;
  links: ArtemisFooterColumnLink[];
}

/** A profile or contact link drawn as an icon. Its label names the link for screen readers, and is its tooltip where the layout has one. */
export interface ArtemisFooterSocialLink extends ArtemisFooterLink {
  /** The icon. Without one, the link keeps the icon the layout draws in that position. */
  icon?: ComponentType<{ className?: string }>;
}

/** A picture, and the words that describe it. */
export interface ArtemisFooterImage {
  src: string;
  alt: string;
}

/** An email sign-up form. */
export interface ArtemisFooterNewsletter {
  /** The heading over the form. */
  title: string;
  /** A line under the heading. */
  text: string;
  /** Sample text in the empty email field. */
  placeholder: string;
  /** The button. */
  button: string;
  /** The button while the address is being sent. */
  sending: string;
  /** The button once the address is sent. */
  sent: string;
}

/** A live clock for one city. */
export interface ArtemisFooterClock {
  /** The city named beside the clock face. */
  city: string;
  /** The city's IANA time zone, such as "Europe/Copenhagen". The clock stays blank if the zone is unknown. */
  timeZone: string;
  /** A line over the time. */
  caption: string;
}

/** The words on an Artemis footer. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisFooterContent {
  /** The name beside the logo mark, and where it links. All layouts; wordmark, spotlight and mega show the name without a link, and wordmark and spotlight also draw it large across the foot. */
  brand: ArtemisFooterLink;
  /** A sentence about the brand. landscape, studio, local-time, frame, spotlight, mega and cta. */
  tagline?: string;
  /** The footer's main line. panorama and wordmark show it as a heading, landscape as a line under `tagline`, studio as a line over `cta`. */
  headline?: string;
  /** The styled end of the headline. It goes with `headline`: give `headline` alone and it shows alone, give both and both show. panorama, wordmark and landscape style it; studio runs it on after `headline`. */
  headlineAccent?: string;
  /** A paragraph under the headline. panorama. */
  subhead?: string;
  /** The main link. panorama and wordmark show it as a button, studio as a large underlined link. */
  cta?: ArtemisFooterLink;
  /** A quieter button beside `cta`. panorama. */
  secondaryCta?: ArtemisFooterLink;
  /** A short status, such as availability. studio and mega show it in a pill with a dot. */
  status?: string;
  /** A picture. panorama shows it wide; studio shows it over `location`. */
  image?: ArtemisFooterImage;
  /** Where you are, beside a map pin. studio. */
  location?: string;
  /** A row of links without headings. panorama and studio, which list the links of `columns` instead when you give only those. */
  links?: ArtemisFooterLink[];
  /** Columns of links under small headings. wordmark, landscape, local-time, frame, spotlight, mega and cta. */
  columns?: ArtemisFooterColumn[];
  /** An email sign-up form. mega. */
  newsletter?: ArtemisFooterNewsletter;
  /** A live clock for one city. local-time. */
  clock?: ArtemisFooterClock;
  /** Icon links to profiles or email. panorama, landscape, studio, frame, mega and cta. */
  social?: ArtemisFooterSocialLink[];
  /** The copyright line. All layouts but landscape. */
  legal?: string;
  /** Small links beside the copyright line. panorama, studio, local-time, frame and cta. */
  legalLinks?: ArtemisFooterLink[];
  /** A short closing line near the copyright. wordmark, frame and spotlight. */
  note?: string;
}

"use client";
// @zeus-internal
import { MotionConfig, motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT, ARTEMIS_SPRING_PRESS } from "../../../lib/ease";
import type { ArtemisFooterContent } from "../content";
const WORDMARK_TRANSITION = { duration: 0.8, ease: ARTEMIS_EASE_OUT } as const;
const DEFAULT = {
    brand: { label: "Zeus", href: "/" },
    headline: "Less busywork.",
    headlineAccent: "More room to grow.",
    cta: { label: "Explore Zeus", href: "/" },
    columns: [
        { title: "Company", links: [{ label: "Our story", href: "/about" }, { label: "Careers", href: "/careers" }, { label: "Journal", href: "/blog" }] },
        { title: "Connect", links: [{ label: "Instagram", href: "https://instagram.com" }, { label: "X", href: "https://x.com" }, { label: "LinkedIn", href: "https://linkedin.com" }] },
        { title: "Legal", links: [{ label: "Privacy policy", href: "/privacy" }, { label: "Terms of service", href: "/terms" }] },
    ],
    legal: "\u00A9 2026 Zeus. All rights reserved.",
    note: "Made with care, from everywhere.",
} satisfies ArtemisFooterContent;
/** Links to other sites open in a new tab. */
const newTab = (href: string) => (/^https?:/.test(href) ? { target: "_blank", rel: "noreferrer noopener" } : {});
export default function FooterSectionsWordmark({ content }: { content?: Partial<ArtemisFooterContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const reduce = useReducedMotion();
    return (<>
      <footer className="art:isolate art:w-full art:overflow-hidden art:bg-primary/10 art:text-foreground">
        <div className="art:relative art:z-10 art:rounded-b-3xl art:border-b art:border-border art:bg-background">
          <div className="art:mx-auto art:grid art:max-w-7xl art:gap-x-16 art:gap-y-12 art:px-6 art:pt-12 art:pb-8 art:@min-[640px]/artemis:px-10 art:@min-[640px]/artemis:pt-16 art:@min-[1024px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:gap-y-28">
            <div>
              <h2 className="art:max-w-md art:text-balance art:text-3xl art:font-normal art:leading-tight art:tracking-tight">
                {copy.headline}
                {accent ? (<span className="art:block art:text-muted-foreground">
                  {accent}
                </span>) : null}
              </h2>
              <motion.a whileHover={reduce ? undefined : { scale: 1.01 }} whileTap={reduce ? undefined : { scale: 0.99 }} transition={ARTEMIS_SPRING_PRESS} className="art:inline-flex art:items-center art:justify-center art:font-medium art:select-none art:transition-colors art:disabled:pointer-events-none art:disabled:opacity-50 art:bg-primary art:text-primary-foreground art:hover:bg-primary/90 art:text-sm art:focus-visible:outline-none art:focus-visible:ring-2 art:focus-visible:ring-ring art:focus-visible:ring-offset-2 art:focus-visible:ring-offset-background art:mt-6 art:h-9 art:gap-2 art:px-4 art:rounded-full" href={copy.cta.href} {...newTab(copy.cta.href)} tabIndex={0}>
                {copy.cta.label}
                <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-arrow-up-right art:size-4" aria-hidden="true">
                  <path d="M7 7h10v10"/>
                  <path d="M7 17 17 7"/>
                </svg>
              </motion.a>
            </div>
            <div className="art:grid art:grid-cols-2 art:gap-x-6 art:gap-y-8 art:@min-[640px]/artemis:grid-cols-3">
              {copy.columns.map((column, index) => <nav key={index} aria-label={column.title}>
                <h3 className="art:mb-3 art:text-sm art:text-muted-foreground">
                  {column.title}
                </h3>
                <ul>
                  {column.links.map((link, linkIndex) => <li key={linkIndex}>
                    <a href={link.href} {...newTab(link.href)} className="art:inline-flex art:min-h-10 art:items-center art:rounded-full art:text-sm art:text-foreground art:transition-colors art:hover:text-primary art:focus-visible:outline-2 art:focus-visible:outline-offset-4 art:focus-visible:outline-ring">
                      {link.label}
                    </a>
                  </li>)}
                </ul>
              </nav>)}
            </div>
            <div className="art:@min-[1024px]/artemis:col-start-2">
              <div className="art:mb-4 art:flex art:items-center art:gap-2.5">
                <span aria-hidden="true">
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.5" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-flower2 art:lucide-flower-2 art:size-8" aria-hidden="true">
                    <path d="M12 5a3 3 0 1 1 3 3m-3-3a3 3 0 1 0-3 3m3-3v1M9 8a3 3 0 1 0 3 3M9 8h1m5 0a3 3 0 1 1-3 3m3-3h-1m-2 3v-1"/>
                    <circle cx="12" cy="8" r="2"/>
                    <path d="M12 10v12"/>
                    <path d="M12 22c4.2 0 7-1.667 7-5-4.2 0-7 1.667-7 5Z"/>
                    <path d="M12 22c-4.2 0-7-1.667-7-5 4.2 0 7 1.667 7 5Z"/>
                  </svg>
                </span>
                <span className="art:text-sm art:font-medium">
                  {copy.brand.label}
                </span>
              </div>
              <p className="art:text-xs art:leading-5 art:text-muted-foreground">
                {copy.legal}
              </p>
              <p className="art:text-xs art:leading-5 art:text-muted-foreground">
                {copy.note}
              </p>
            </div>
          </div>
        </div>
        <div aria-hidden="true" className="art:w-full art:overflow-hidden art:pt-5 art:@min-[640px]/artemis:pt-8">
          <MotionConfig reducedMotion="user">
            <motion.div initial={{ opacity: 0, y: 30 }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, amount: 0.15 }} transition={WORDMARK_TRANSITION}>
            <svg aria-hidden="true" viewBox="0 38 390 98" className="art:block art:h-auto art:w-full art:overflow-visible art:text-background art:dark:text-foreground/80">
              <text x="0" y="136" textLength="390" lengthAdjust="spacingAndGlyphs" fill="currentColor" className="art:font-sans art:text-9xl art:font-medium">
                {copy.brand.label}
              </text>
            </svg>
            </motion.div>
          </MotionConfig>
        </div>
      </footer>
    </>);
}
